-- ===== محرك التسعير بالتحليل: الموارد والوصفات (للمالك فقط) =====
create table if not exists public.price_resources(code text primary key, kind text not null check (kind in ('mat','lab','eqp','cfg')), name text not null, unit text not null, price numeric not null default 0, src text);
create table if not exists public.price_recipes(code text primary key, section text not null, name text not null, unit text not null, comps jsonb not null default '[]', pub boolean not null default true);
alter table public.price_resources enable row level security; alter table public.price_recipes enable row level security;
drop policy if exists "owner only" on public.price_resources; drop policy if exists "owner only" on public.price_recipes;
create policy "owner only" on public.price_resources for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "owner only" on public.price_recipes for all to authenticated using (public.is_owner()) with check (public.is_owner());
revoke all on public.price_resources, public.price_recipes from anon;
on conflict (code) do nothing;
on conflict (code) do nothing;
